import{_ as e,o as t,c as s,a2 as n}from"./chunks/framework.DSQXGnvq.js";const m=JSON.parse('{"title":"基本定律 (Fundamental Laws)","description":"","frontmatter":{},"headers":[],"relativePath":"examples/fundamental-laws/index.md","filePath":"examples/fundamental-laws/index.md"}'),l={name:"examples/fundamental-laws/index.md"};function p(r,a,i,o,d,c){return t(),s("div",null,[...a[0]||(a[0]=[n('<h1 id="基本定律-fundamental-laws" tabindex="-1">基本定律 (Fundamental Laws) <a class="header-anchor" href="#基本定律-fundamental-laws" aria-label="Permalink to &quot;基本定律 (Fundamental Laws)&quot;">​</a></h1><p>本节讨论电子学的基本定律。</p><h2 id="基尔霍夫电路定律-kirchhoff-s-circuit-laws" tabindex="-1">基尔霍夫电路定律 (Kirchhoff&#39;s circuit laws) <a class="header-anchor" href="#基尔霍夫电路定律-kirchhoff-s-circuit-laws" aria-label="Permalink to &quot;基尔霍夫电路定律 (Kirchhoff&#39;s circuit laws)&quot;">​</a></h2><p>基尔霍夫电路定律是关于电路中电流和电压的两个等式约束，在特定近似条件下成立。</p><p>**基尔霍夫电流定律（KCL）**指出，电路中任意节点处，流入该节点的电流之和等于流出该节点的电流之和：</p><p>[\\sum_{k=1}^n {I}_k = 0]</p><p>这一定律本质上是通量守恒的普遍原理。</p><p>**基尔霍夫电压定律（KVL）**指出，网络中沿闭合回路的各支路电压之和为零：</p><p>[\\sum_{k=1}^n {V}_k = 0]</p><p>SPICE 使用基尔霍夫电路定律来求解电路中的电压和电流。欲深入了解这些等式，可在线阅读《费曼物理学讲义》第二卷第 22-3 节。</p><h2 id="欧姆定律-ohm-s-law" tabindex="-1">欧姆定律 (Ohm&#39;s Law) <a class="header-anchor" href="#欧姆定律-ohm-s-law" aria-label="Permalink to &quot;欧姆定律 (Ohm&#39;s Law)&quot;">​</a></h2><p>欧姆定律是一个简单的电阻模型，它指出流过电阻的电流 I 与施加在其两端的电压 U 成正比，比例常数称为电阻（R）。</p><p>[U = R I]</p><p>这类似于管道中充满水的现象——水的流速与管道的倾斜度成正比，倾斜度越大，水压越高。电子好比水，电压好比压力。</p><p>实际上，电阻与材料的温度有关，就像许多器件参数一样。因此，我们总是在指定温度下仿真电路。</p><p>这一定律在电路分析中非常重要，因为它是任何二端元件在特定电流和电压下的一阶近似。实际上，我们可以通过线性关系近似局部任意曲线。如果我们知道某二端元件在特定条件下的电流和电压，就可以近似其在电流或电压微小变化下的变化率。SPICE 正是利用这一原理在不同时间点求解电路。</p><p>本节包含 3 个文档。</p>',17)])])}const u=e(l,[["render",p]]);export{m as __pageData,u as default};
